css:
.print-heading { display: none !important; }
.print-format, .print-format * { box-sizing: border-box; }

html, body,
.print-format,
.print-format * {
  font-family: Calibri, Carlito, Arial, Helvetica, sans-serif !important;
}

.print-format {
  font-size: 11pt !important;
  font-weight: 400 !important;
  color: #000 !important;
  padding: 5mm 8mm !important;
  margin: 0 auto !important;
  letter-spacing: 0 !important;
  background: #fff !important;
}

@page {
  size: A4 portrait;
  margin: 5mm 8mm !important;
}

html, body {
  margin: 0 !important;
  padding: 0 !important;
  background: #fff !important;
}

.register {
  width: 100%;
  color: #000;
}

.reg-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin: 3.5mm 0 1.5mm 0;
}
.reg-title {
  font-size: 20pt !important;
  font-weight: 700 !important;
  line-height: 1;
}
.reg-part {
  font-size: 11pt !important;
  font-weight: 600 !important;
  line-height: 1;
}

.row {
  display: flex;
  align-items: flex-end;
  height: 4mm;
  margin: 0;
  padding: 0;
}
.lbl {
  flex: 0 0 auto;
  white-space: nowrap;
  font-size: 11pt !important;
  font-weight: 600 !important;
  line-height: 1;
  padding: 0 2.5mm 1px 0;
}
.line + .lbl {
  padding-left: 4mm;
}
.line {
  flex: 1 1 0;
  min-width: 10mm;
  border-bottom: 1px solid #000;
  min-height: 4.4mm;
  height: auto;
  padding: 0 2px 3px;
  font-size: 11pt !important;
  font-weight: 400 !important;
  line-height: 1;
  overflow: visible;
}
.grow-2 { flex: 1.4 1 0; }
.grow-1 { flex: 0.65 1 0; }

.after-lin {
  height: 4mm;
  margin-bottom: 3.5mm;
}

.bio {
  display: grid;
  grid-template-columns: 30mm 1fr;
  column-gap: 6mm;
  margin-top: 0;
  align-items: start;
}
.photo-box {
  width: 30mm;
  height: 35mm;
  border: 1px solid #000;
  text-align: center;
  overflow: hidden;
  font-size: 11pt !important;
  font-weight: 600 !important;
}
.photo-box .photo-ph {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.photo-box img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.bio-fields { min-width: 0; }
.bio-fields .row { height: 4mm; }

.body { margin-top: 0.8mm; }
.body .row { height: 4mm; }
.body .row.rcol > .right {
  flex: 0 0 50%;
  display: flex;
  align-items: flex-end;
  min-width: 0;
  height: 100%;
  padding-left: 4mm;
}

.lines-2 .row { height: 4mm; }
.lines-3 { margin-top: 6.5mm; }
.lines-3 .row { height: 4mm; }

.sigs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  column-gap: 10mm;
  margin-top: 6.5mm;
  padding: 0 10mm;
}
.sig-box {
  height: 32mm;
  border: 1px solid #000;
  text-align: center;
  font-size: 11pt !important;
  font-weight: 600 !important;
  line-height: 1;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding-bottom: 3mm;
  padding-top: 0;
}

.notes {
  margin-top: 2.5mm;
  padding-top: 0;
  border-top: none;
  font-size: 9.5pt !important;
  font-weight: 400 !important;
  line-height: 1.2;
  page-break-before: avoid;
  break-before: avoid;
}

@media screen {
  .print-format {
    width: 210mm !important;
    max-width: 210mm !important;
    min-height: 297mm !important;
    padding: 5mm 8mm !important;
    border-radius: 0 !important;
  }
}

@media print {
  @page { size: A4 portrait; margin: 5mm 8mm !important; }
  html, body {
    margin: 0 !important;
    padding: 0 !important;
    width: auto !important;
    min-height: 0 !important;
    height: auto !important;
  }
  .print-format {
    padding: 0 !important;
    margin: 0 !important;
    width: auto !important;
    max-width: none !important;
    min-height: 0 !important;
    height: auto !important;
    display: block !important;
  }
  .notes {
    page-break-before: avoid;
    break-before: avoid;
  }
}
